INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fda836a-d60f-48fb-a13c-86f01ab6c3bc', '2e1b0ceb-ed68-41e3-80a8-270bdc469815', 0, 'Confidentiality, since any unauthorized access always violates confidentiality regardless of what the attacker actually did.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01d06ca1-5f1e-4ebd-ba1b-785869013514', '2e1b0ceb-ed68-41e3-80a8-270bdc469815', 1, 'Integrity, since the data was altered without authorization — integrity specifically means data has not been improperly modified, regardless of whether it remains readable or available.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ca68023-48c6-4007-bdb4-444acc6afacf', '2e1b0ceb-ed68-41e3-80a8-270bdc469815', 2, 'Availability, since any security incident automatically counts as an availability violation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a20041e-aecd-4fb3-ae5e-56c98fc906e0', '2e1b0ceb-ed68-41e3-80a8-270bdc469815', 3, 'None of the three — unauthorized modification does not fall under the CIA triad at all.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ba1f24a-ea14-4367-8280-65eeddd3736b', '743b6d76-7827-4a60-943e-6a476fa40d3c', 0, 'Symmetric encryption (e.g., AES) is efficient for encrypting large volumes of data since both parties use the same key; asymmetric encryption (e.g., RSA) uses a public/private key pair, which solves the key-exchange problem without needing a pre-shared secret.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8b24891-77fb-45ab-aac8-0e77e18ae615', '743b6d76-7827-4a60-943e-6a476fa40d3c', 1, 'Asymmetric encryption should be used for both needs, since it is always faster than symmetric encryption for bulk data.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37f6775b-eb1f-45c0-92f6-3a559221f67a', '743b6d76-7827-4a60-943e-6a476fa40d3c', 2, 'Symmetric encryption should be used for both needs, since a shared key can always be exchanged safely without any additional protocol.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('350b4472-053c-448a-a9be-f11869c91def', '743b6d76-7827-4a60-943e-6a476fa40d3c', 3, 'Hashing algorithms (e.g., SHA-256) should be used for both needs, since hashing is reversible and provides the same key-exchange capability as asymmetric encryption.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69ec5f39-58b3-43ac-93fe-2d67ac206016', '7288ed4a-bed3-45ba-9826-acb22281bef3', 0, 'Generic phishing, since all fraudulent emails regardless of targeting or personalization are called phishing with no further distinction.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0fc2740d-4ac2-45d0-b222-33de4db945bf', '7288ed4a-bed3-45ba-9826-acb22281bef3', 1, 'Whaling — a spear-phishing attack specifically targeting a high-profile individual (like a C-suite executive) with a highly personalized, researched pretext, distinct from broader, less-targeted phishing.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0883ba5d-e302-4d8e-a9ef-7f6adb7ea352', '7288ed4a-bed3-45ba-9826-acb22281bef3', 2, 'Vishing, since vishing specifically refers to any attack that references internal company information.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('378eb80e-b8dc-448c-a733-09f0dee3d673', '7288ed4a-bed3-45ba-9826-acb22281bef3', 3, 'Tailgating, since tailgating refers to any social engineering attack conducted via email.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1059a810-02a0-495c-95e1-e89a8f33a490', '43739e74-23d3-4ea7-803d-aa4a525c6a6a', 0, 'Cross-Site Scripting (XSS); mitigated by disabling JavaScript in the user''s browser.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9066d86-b316-4eaa-a7f7-277cc30b2e70', '43739e74-23d3-4ea7-803d-aa4a525c6a6a', 1, 'SQL Injection; mitigated by using parameterized queries (prepared statements) so user input is always treated strictly as data, never as executable query logic.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e1f6d83-4e3a-43a7-99b0-a94033e69d81', '43739e74-23d3-4ea7-803d-aa4a525c6a6a', 2, 'A buffer overflow; mitigated by increasing the size of the application''s memory allocation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d31b1ae2-85fd-4ef6-9345-47006ca7a45b', '43739e74-23d3-4ea7-803d-aa4a525c6a6a', 3, 'A denial-of-service attack; mitigated by rate-limiting incoming requests.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c7955f9-ded6-45bb-9376-b1d7ef32c4d4', 'f23ee357-7145-4ce6-9623-2ac4c2f9f9cd', 0, 'Vulnerability scanning — an automated process identifying and cataloguing known weaknesses without exploiting them; penetration testing goes further, actively attempting to exploit identified weaknesses to demonstrate real-world impact, typically involving skilled human testers, not just automated tools.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be147876-ef8f-4129-baec-0a9c6dcdf08e', 'f23ee357-7145-4ce6-9623-2ac4c2f9f9cd', 1, 'Penetration testing — the two terms are fully interchangeable and describe exactly the same activity with no meaningful distinction.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b597234-4f9f-4e08-a24f-27928b8c72b0', 'f23ee357-7145-4ce6-9623-2ac4c2f9f9cd', 2, 'Digital forensics, since identifying software weaknesses is the core definition of digital forensics.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c74a66cd-42c9-4b1b-a121-ecad684896ec', 'f23ee357-7145-4ce6-9623-2ac4c2f9f9cd', 3, 'Threat hunting, since threat hunting is defined as any automated, non-exploitative security scan.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('99970ee7-5f51-4821-bfc5-fab4681b7ed4', '01a3d765-82b8-4c90-922f-6a7b4d2d20bb', 0, 'A worm; the immediate recommended response is to pay the ransom to recover the files as quickly as possible.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0b7b6a3-0238-4089-9cf1-3f06ec991af0', '01a3d765-82b8-4c90-922f-6a7b4d2d20bb', 1, 'Ransomware; the immediate recommended response is to isolate/disconnect the infected system from the network to prevent further spread, then follow the organization''s incident response process (do not pay, and do not assume payment guarantees recovery).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3255dd72-dff0-40e4-8a60-187a35244a70', '01a3d765-82b8-4c90-922f-6a7b4d2d20bb', 2, 'A rootkit; the immediate recommended response is to ignore the message, since rootkits cannot actually encrypt files.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b40d82b3-cbbe-485f-bfbd-59a5c9fbd95a', '01a3d765-82b8-4c90-922f-6a7b4d2d20bb', 3, 'A Trojan; the immediate recommended response is to run a full disk defragmentation to remove the malware.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77864f01-2704-4bfc-a099-34cda0405f81', '0a44d3c6-faed-4087-a089-1637e29be79d', 0, 'Perimeter-based security, since it assumes anything inside the network boundary is inherently trustworthy.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('540ad533-eccf-4725-a7f4-0e7018ea75a9', '0a44d3c6-faed-4087-a089-1637e29be79d', 1, 'Zero Trust — every access request is authenticated and authorized on its own merits regardless of network location, treating internal and external requests with equal scrutiny.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d49d04c3-13dc-4037-ad90-6963d179d52d', '0a44d3c6-faed-4087-a089-1637e29be79d', 2, 'Full trust architecture, since granting broad implicit trust is the actual definition of this model.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38dd3157-e60c-4428-b5b1-dcb152458e85', '0a44d3c6-faed-4087-a089-1637e29be79d', 3, 'Single sign-on (SSO), since SSO and Zero Trust describe the same underlying security model.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12d58abc-5ef9-42ab-9b54-2387e2a841b7', '3c958027-a2fe-4e31-ae50-7176909a857c', 0, 'A DMZ (demilitarized zone) — a separate network segment where public-facing servers are placed, isolated by firewalls from both the internet and the internal network, so a compromised DMZ host does not directly expose internal systems.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e883b6f-6cc3-473b-944f-2a15ebcb2a56', '3c958027-a2fe-4e31-ae50-7176909a857c', 1, 'Placing the web server directly on the internal network alongside all other corporate systems, since network segmentation provides no meaningful security benefit.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('daad7411-51f0-42c5-8ab9-b09d9e7d0566', '3c958027-a2fe-4e31-ae50-7176909a857c', 2, 'Disabling all firewalls, since firewalls are only relevant for internal traffic, not public-facing servers.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('289ac44c-6817-43f9-a39b-f68d421ee373', '3c958027-a2fe-4e31-ae50-7176909a857c', 3, 'Using a single flat network with no segmentation, relying entirely on antivirus software on each host.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3596e4f-8d61-4b90-82d4-f259d074b84b', '37072e88-cb89-4932-8351-32a205d24b08', 0, 'Defense in depth — layering multiple, independent security controls so no single point of failure compromises the entire system.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('341f7f62-6fdd-4073-8f7a-250d00838f09', '37072e88-cb89-4932-8351-32a205d24b08', 1, 'Security through obscurity, since hiding the existence of multiple controls from attackers is the actual mechanism at work.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb0f62b2-e255-42c1-90ac-84fede8babea', '37072e88-cb89-4932-8351-32a205d24b08', 2, 'Single point of failure design, since combining many controls always creates one larger point of failure.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac20600d-9e04-438b-b111-af95d588172b', '37072e88-cb89-4932-8351-32a205d24b08', 3, 'Least privilege, since using many different tools is the definition of least privilege.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('531a8c34-9346-4d1c-beee-76949eca499b', '002669c6-2b06-427d-b91b-00980451645c', 0, 'A SIEM (Security Information and Event Management) system, which centralizes log aggregation, correlation, and real-time alerting across many disparate log sources.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e17d0057-7e44-4eb2-b9be-c1749a095996', '002669c6-2b06-427d-b91b-00980451645c', 1, 'A single antivirus agent, since antivirus alone aggregates and correlates logs from firewalls and servers across an entire organization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8dd940c-f422-4465-a77f-5db880ef7075', '002669c6-2b06-427d-b91b-00980451645c', 2, 'A single Network ACL, since NACLs are designed to aggregate and correlate logs from multiple systems.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe538b76-063a-44c3-a081-8c59de447be7', '002669c6-2b06-427d-b91b-00980451645c', 3, 'A password manager, since centralizing credentials is the same function as centralizing log data.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e767128-ff43-4550-9fd1-8e977eb894ad', 'ea2613c4-89f8-49b5-9bbc-a70ec16d97a1', 0, 'Eradicate → Contain → Recover → Lessons Learned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76408652-ee89-49c6-94e6-7dfafcd43c13', 'ea2613c4-89f8-49b5-9bbc-a70ec16d97a1', 1, 'Contain → Eradicate → Recover → Lessons Learned — stop the attack from spreading first, then remove the threat entirely, then restore normal operations, then review what happened to improve future response.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89dd6758-fc07-46aa-b495-ec01c4e91afc', 'ea2613c4-89f8-49b5-9bbc-a70ec16d97a1', 2, 'Recover → Contain → Eradicate → Lessons Learned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bcd33df3-38fd-4472-bdf9-4dc1da4725d7', 'ea2613c4-89f8-49b5-9bbc-a70ec16d97a1', 3, 'Lessons Learned → Contain → Eradicate → Recover');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('781212b5-6625-42e7-bd8b-d921e9e44222', '2e264f8a-67dd-4d29-a4be-37357e96c3ea', 0, 'Multi-factor authentication (MFA), combining "something you know" (the password) with "something you have" (the phone generating the code).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9171188e-421a-4b2b-aecb-2550c235fde4', '2e264f8a-67dd-4d29-a4be-37357e96c3ea', 1, 'Single-factor authentication, since a password and an app-generated code are actually the same factor category repeated twice.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f13d0b68-e0f8-4105-a62b-c28b5e1f24f3', '2e264f8a-67dd-4d29-a4be-37357e96c3ea', 2, 'Biometric authentication, since any second authentication step is automatically classified as biometric.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2bb8a7e1-66b8-4fda-9dd4-345e0c28fa72', '2e264f8a-67dd-4d29-a4be-37357e96c3ea', 3, 'Federated identity, since using an app to generate a code is the definition of federated identity.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('688c73f9-9d76-433e-9526-e2669d17cb11', 'd9e73dbe-10e8-4fc0-90d4-e361b3f4f035', 0, 'Least privilege — granting each user only the minimum access necessary to perform their specific job function, and nothing beyond that.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5ceee40-ef07-4bb6-935e-5a76f816fa08', 'd9e73dbe-10e8-4fc0-90d4-e361b3f4f035', 1, 'Mandatory access control, since granting minimum necessary access is the literal definition of mandatory access control specifically.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('841140e4-bee8-4e55-b9b5-f3005ff4d417', 'd9e73dbe-10e8-4fc0-90d4-e361b3f4f035', 2, 'Discretionary access control, since only DAC ever restricts user access based on job role.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07114999-d538-4b71-b5b4-eb44d1bd8521', 'd9e73dbe-10e8-4fc0-90d4-e361b3f4f035', 3, 'Maximum privilege, since granting broad access by default is the standard secure practice.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2a03f3c-a4f5-46d0-b727-f14e6981b8b7', '4e188e4c-fb2b-4149-8fe4-7eb5bc4fa560', 0, 'Chain of custody — a documented, unbroken record of who possessed the evidence, when, and what was done to/with it at every step, from collection through presentation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e918d88-f2d7-4e69-a024-9060c7db42fe', '4e188e4c-fb2b-4149-8fe4-7eb5bc4fa560', 1, 'A non-disclosure agreement, since NDAs are the specific legal document that establishes evidence admissibility.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a601b63-67eb-48fd-a2a8-60e65176cf1e', '4e188e4c-fb2b-4149-8fe4-7eb5bc4fa560', 2, 'A service level agreement, since SLAs govern how forensic evidence must be documented.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f34ad1f-4ef6-417b-a9ba-8f69da11cee5', '4e188e4c-fb2b-4149-8fe4-7eb5bc4fa560', 3, 'No formal documentation is required as long as the investigator is trustworthy.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98a8934e-f3b3-4c60-97f8-8309c1e7daff', '11a47279-42f8-4029-a57e-691818cea9dd', 0, 'EDR (Endpoint Detection and Response) — monitors endpoint behavior continuously and can detect and respond to suspicious activity patterns even without a matching known malware signature.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85286d4d-8327-4ed1-8f0f-5a93aa7fd286', '11a47279-42f8-4029-a57e-691818cea9dd', 1, 'Traditional signature-based antivirus, since signature matching is equally capable of detecting previously unseen malware variants.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21fa7096-4040-4b1d-927a-ebb833c7c520', '11a47279-42f8-4029-a57e-691818cea9dd', 2, 'A firewall, since firewalls monitor individual process behavior on an endpoint in real time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a408ce07-aacc-42d8-84a5-1ae5291c16dc', '11a47279-42f8-4029-a57e-691818cea9dd', 3, 'A VPN, since VPNs are designed to detect and respond to malicious process behavior on the endpoint.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a215ce82-56b9-4550-a57e-f3cd7fcddd7d', '217ea96e-4702-4ce2-977f-2b7b608ea0db', 0, 'The unpatched software flaw is the vulnerability (a weakness that could be exploited); the ransomware groups actively targeting this flaw are the threat (a potential source of harm); the risk is the resulting likelihood and impact of that threat actually exploiting that vulnerability against this specific server.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db6fcc5a-cd6d-499a-8203-e962f8468836', '217ea96e-4702-4ce2-977f-2b7b608ea0db', 1, 'Threat, vulnerability, and risk are fully interchangeable terms describing the exact same concept in this scenario.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ac6c646-12c3-440d-ae1f-e059cfe67cfa', '217ea96e-4702-4ce2-977f-2b7b608ea0db', 2, 'The unpatched software flaw is the threat, and the ransomware groups are the vulnerability.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc740336-275b-46fa-b293-2a0f1fce254f', '217ea96e-4702-4ce2-977f-2b7b608ea0db', 3, 'Risk refers only to financial loss and has no relationship to threats or vulnerabilities.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59eac8fa-df24-4330-bc57-0c425a4b919a', '0d480b91-5312-467c-a705-a2e969617f0d', 0, 'PCI-DSS, which is the specific framework governing patient health information protection.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3133049c-09c7-4a7a-8521-796472117b1c', '0d480b91-5312-467c-a705-a2e969617f0d', 1, 'HIPAA (Health Insurance Portability and Accountability Act), the US regulatory framework specifically governing the privacy and security of protected health information (PHI).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0c624dc-a915-4cd8-abc8-f67de99ff8e1', '0d480b91-5312-467c-a705-a2e969617f0d', 2, 'GDPR is the only compliance framework that exists globally, applying identically to all industries including healthcare with no distinct healthcare-specific framework.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5676f75f-c1c9-40af-95e2-6eb1e49c20fd', '0d480b91-5312-467c-a705-a2e969617f0d', 3, 'Compliance frameworks are voluntary in every jurisdiction and never carry legal requirements for healthcare data.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3ba13d6-7148-433b-921f-96940001d82b', '23253ff6-4e9f-43d3-9c17-3981c02ec8b1', 0, 'This is a technical control, and it is redundant once email filtering and EDR are already deployed, providing no additional value.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11a10362-c83b-41a5-9c35-16768b5c4c95', '23253ff6-4e9f-43d3-9c17-3981c02ec8b1', 1, 'This is a security awareness/training control (a category of administrative/managerial control) — emphasized because humans are frequently the weakest link that purely technical controls cannot fully address; a well-trained employee can catch a sophisticated phishing attempt that slips past automated filtering.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81161c8b-041f-494f-b7e2-a91e21a4ae86', '23253ff6-4e9f-43d3-9c17-3981c02ec8b1', 2, 'This is a physical control, since training occurs in a physical location such as a classroom or office.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6cbf6d0b-84ef-4809-b5c0-d183191186ae', '23253ff6-4e9f-43d3-9c17-3981c02ec8b1', 3, 'Security awareness training has no formal classification and does not belong to any recognized control category.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e297be92-dd7d-4c39-8131-6f0116d1f15e', '27766f16-9e68-4884-af7f-fe70cd890d28', 0, 'Business Continuity Planning (BCP) focuses on keeping critical BUSINESS functions running (potentially via manual workarounds or alternate sites) during and immediately after a disruption; Disaster Recovery (DR) focuses specifically on restoring IT systems and infrastructure to normal operation — related but genuinely distinct scopes.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a69cd3d7-3056-4ecb-84dc-216c1ec4c541', '27766f16-9e68-4884-af7f-fe70cd890d28', 1, 'BCP and DR are fully interchangeable terms describing the exact same plan with no meaningful distinction in scope.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5e545b3-d444-4d62-a279-4ab059cdf183', '27766f16-9e68-4884-af7f-fe70cd890d28', 2, 'BCP applies only to IT systems, while DR applies only to non-technical business operations — the reverse of the actual definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16a96e5f-0dd0-4c96-b63a-d7827bf4de1b', '27766f16-9e68-4884-af7f-fe70cd890d28', 3, 'Neither BCP nor DR are real, formally defined planning concepts within security program management.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe3516eb-9fee-48f5-a5ea-94535011c011', '9c1630f4-2922-48c8-818b-f4ae91d29bcc', 0, 'Risk avoidance, since choosing not to implement a control is the same as avoiding the risk entirely.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3967f35-3a9f-46a8-9ce5-0db54c37d27c', '9c1630f4-2922-48c8-818b-f4ae91d29bcc', 1, 'Risk transference, since documenting a decision transfers the risk to another party automatically.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b04f4b7-7ea4-4370-ad72-73b342093522', '9c1630f4-2922-48c8-818b-f4ae91d29bcc', 2, 'Risk acceptance — a deliberate, documented decision to take no additional mitigating action because the cost of mitigation outweighs the potential impact, formally acknowledging and owning the remaining risk.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d403b93e-3de6-45c3-ae6d-9e46b6910cfe', '9c1630f4-2922-48c8-818b-f4ae91d29bcc', 3, 'Risk mitigation, since documenting the decision is itself considered a form of active mitigation.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
